// Atmosphere per theme, derived from its catalogue entry (list.ts): which demo backsound plays, which ambient particles
// drift over the page and how the cover opens. ThemeShell reads it once per theme; nothing here is theme-specific code.
import { themeList } from "./list";
import { motionOf } from "./motion";

/** Demo backsound tracks in /public/music/demo (generated by tools/audio/demo_music.py). */
export type Mood = "romantis" | "gamelan" | "nusantara" | "religi" | "akustik" | "ceria" | "khidmat";
/** Particles drawn by <Ambient> while the guest reads. */
export type AmbientKind = "petals" | "gold" | "glow" | "leaves" | "confetti" | "sparkle" | "none";
/** How the cover leaves when the guest taps "Buka undangan". */
export type CoverExit = "doors" | "iris" | "rise" | "pop" | "lift";

export type ThemeMood = { mood: Mood; ambient: AmbientKind; cover: CoverExit; burst: boolean };

// Regions whose wedding music is gamelan (or a close relative such as gambang kromong).
const GAMELAN = new Set(["Adat Jawa", "Adat Bali", "Adat Sunda", "Adat Cirebon", "Adat Osing", "Adat Tengger", "Adat Madura", "Adat Banten", "Adat Betawi", "Adat Sasak"]);
const RELIGI_EVENTS = new Set(["Pengajian", "Tahlilan", "Buka Bersama"]);
const RELIGI_IDS = new Set(["pulang-haji", "walimatus-safar", "khataman-quran", "maulid-nabi", "isra-miraj", "haul-tahlil", "wisuda-santri", "pengajian-akbar"]);
const KHIDMAT_EVENTS = new Set(["Wisuda", "Pelantikan", "Peresmian", "Seminar", "Peluncuran", "Perpisahan", "Natal", "Paskah", "Baptis", "Pameran"]);
const ROMANTIS_EVENTS = new Set(["Tunangan", "Bridal Shower", "Ulang Tahun Pernikahan"]);
const OUTDOOR = new Set(["Boho", "Garden", "Pantai", "Pemandangan", "Rustic", "Cat Air", "Gambar Tangan", "Ilustrasi"]);
// App, social-media and other "kekinian" mock-ups: their UI is the joke, so no particles over it.
const KEKINIAN = new Set(["Aplikasi", "Hiburan", "Sosial Media", "Perjalanan", "Keuangan", "Belanja", "Unik"]);

// Wedding styles that suit something other than the mood's default particles.
const AMBIENT_BY_CATEGORY: Record<string, AmbientKind> = {
  Luxury: "sparkle", Elegan: "sparkle", Modern: "sparkle", "Ulang Tahun Pernikahan": "sparkle", Minimalis: "none",
};
const AMBIENT: Record<Mood, AmbientKind> = {
  romantis: "petals", gamelan: "gold", nusantara: "gold", religi: "glow", akustik: "leaves", ceria: "confetti", khidmat: "sparkle",
};
const COVER: Record<Mood, CoverExit> = {
  romantis: "iris", gamelan: "doors", nusantara: "doors", religi: "iris", akustik: "rise", ceria: "pop", khidmat: "iris",
};

function moodFor(id: string, category: string, group: string): Mood {
  if (RELIGI_IDS.has(id) || group === "islami" || category === "Islami" || category === "Syari" || RELIGI_EVENTS.has(category)) return "religi";
  if (category === "Siraman" || GAMELAN.has(category)) return "gamelan";
  if (category.startsWith("Adat ") || category === "Peranakan" || category === "Imlek") return "nusantara";
  if (KHIDMAT_EVENTS.has(category)) return "khidmat";
  if (ROMANTIS_EVENTS.has(category)) return "romantis";
  if (category === "Syukuran") return "akustik";
  // Elegant birthdays (a parent's 60th, a gala) get the stately piano instead of the party track.
  if (group === "acara") return category === "Ulang Tahun" && motionOf(id) === "elegant" ? "khidmat" : "ceria";
  if (KEKINIAN.has(category)) return "ceria";
  if (OUTDOOR.has(category)) return "akustik";
  return "romantis";
}

const cache = new Map<string, ThemeMood>();

export function themeMood(id?: string): ThemeMood {
  const key = id ?? "";
  const hit = cache.get(key);
  if (hit) return hit;
  const meta = themeList.find(theme => theme.id === id);
  const category = meta?.category ?? "";
  const mood = meta ? moodFor(meta.id, category, meta.group) : "romantis";
  const crisp = motionOf(id) === "crisp";
  const kekinian = KEKINIAN.has(category);
  const result: ThemeMood = {
    mood,
    ambient: crisp || kekinian ? "none" : AMBIENT_BY_CATEGORY[category] ?? AMBIENT[mood],
    cover: crisp ? "lift" : kekinian ? "pop" : COVER[mood],
    // A small burst of petals / confetti from the open button, only where it suits the occasion.
    burst: !crisp && !kekinian && (mood === "romantis" || mood === "ceria"),
  };
  cache.set(key, result);
  return result;
}

/** Demo backsound for a theme (the invitation demo page plays it; real invitations use the couple's own upload). */
export function demoMusic(id?: string) {
  const { mood } = themeMood(id);
  return { url: `/music/demo/${mood}.mp3`, autoplay: true, title: DEMO_TITLES[mood], bpm: DEMO_BPM[mood] };
}

// Kept in sync with public/music/demo/tracks.json.
const DEMO_TITLES: Record<Mood, string> = {
  romantis: "Piano Romantis", gamelan: "Gamelan Keraton", nusantara: "Kecapi Nusantara", religi: "Doa & Harapan",
  akustik: "Petikan Akustik", ceria: "Ceria", khidmat: "Khidmat",
};
const DEMO_BPM: Record<Mood, number> = { romantis: 70, gamelan: 60, nusantara: 72, religi: 60, akustik: 84, ceria: 112, khidmat: 76 };
